function shuffle(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}

const state = {
  deck: [],      // 打乱的题目（选项也已打乱）
  idx: 0,
  score: 0,
  wrong: [],     // 答错的题目对象
  answered: false,
  startTime: 0,  // 本轮开始时间戳
  modeName: "",  // 本轮模式名称
};

// ---------------- 历史成绩（localStorage，仅存于当前浏览器） ----------------
const HISTORY_KEY = "zz-quiz-history";

function loadHistory(){
  try { return JSON.parse(localStorage.getItem(HISTORY_KEY)) || []; }
  catch { return []; }
}

function saveRecord(rec){
  try {
    const list = loadHistory();
    list.unshift(rec);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(list.slice(0, 100)));
  } catch { /* 隐私模式等场景下静默失败 */ }
}

function clearHistory(){
  try { localStorage.removeItem(HISTORY_KEY); } catch {}
}

function fmtTime(ts){
  const d = new Date(ts);
  const p = n => String(n).padStart(2, "0");
  return `${d.getMonth()+1}月${d.getDate()}日 ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function fmtDur(sec){
  return sec < 60 ? `${sec}秒` : `${Math.floor(sec/60)}分${sec%60}秒`;
}

// 组卷：题序乱序 + 选项乱序
function buildDeck(pool){
  return shuffle(pool).map(q => {
    const order = shuffle([0,1,2,3]);
    return {
      ...q,
      opts: order.map(i => q.o[i]),
      ans: order.indexOf(q.a),
    };
  });
}

function el(html){
  const t = document.createElement("template");
  t.innerHTML = html.trim();
  return t.content.firstElementChild;
}

function renderStart(){
  state.answered = false;
  app.innerHTML = "";
  const sectionBtns = SECTIONS.map((name,i) => {
    const n = QUESTIONS.filter(q => q.s === i).length;
    return `
      <button class="mode" data-mode="sec" data-sec="${i}">
        <span class="tag">${n}题</span>
        <span><span class="name">${name}</span><br><span class="meta">板块内乱序出题</span></span>
      </button>`;
  }).join("");

  const history = loadHistory();
  const historyHtml = history.length ? `
      <div class="history">
        <div class="history-head">
          <h3>历史成绩</h3>
          <button class="btn btn-ghost btn-sm" id="clear-history">清空记录</button>
        </div>
        <table>
          <thead><tr><th>时间</th><th>模式</th><th>得分</th><th>正确率</th><th>用时</th></tr></thead>
          <tbody>
            ${history.map(h => `
              <tr>
                <td>${fmtTime(h.t)}</td>
                <td>${h.mode}</td>
                <td><b>${h.score}</b> / ${h.total}</td>
                <td>${Math.round(h.score/h.total*100)}%</td>
                <td>${fmtDur(h.dur)}</td>
              </tr>`).join("")}
          </tbody>
        </table>
      </div>` : "";

  app.appendChild(el(`
    <div class="hero">
      <h2 class="serif">今天复习的考点，<br>刷一遍就知道牢不牢。</h2>
      <p>选自「四选一重要考点汇总」九大板块，共 ${QUESTIONS.length} 题。点选后立即判分并显示解析，题目与选项均已随机打乱。</p>
      <div class="mode-list">
        <button class="mode" data-mode="all">
          <span class="tag">全部</span>
          <span><span class="name">全套乱序刷题</span><br><span class="meta">${QUESTIONS.length} 题 · 九个板块混合</span></span>
        </button>
        ${sectionBtns}
      </div>
      ${historyHtml}
      <p class="tip">历史成绩保存在本浏览器中，清理浏览器数据后记录会消失。</p>
    </div>`));
  app.querySelectorAll(".mode").forEach(b => b.addEventListener("click", () => {
    const pool = b.dataset.mode === "all"
      ? QUESTIONS
      : QUESTIONS.filter(q => q.s === Number(b.dataset.sec));
    startQuiz(pool, b.dataset.mode === "all" ? "全套乱序" : SECTIONS[Number(b.dataset.sec)]);
  }));
  const clearBtn = app.querySelector("#clear-history");
  if(clearBtn) clearBtn.addEventListener("click", () => {
    clearHistory();
    renderStart();
  });
}

function startQuiz(pool, modeName){
  state.deck = buildDeck(pool);
  state.idx = 0;
  state.score = 0;
  state.wrong = [];
  state.startTime = Date.now();
  state.modeName = modeName || "错题重练";
  renderQuestion();
}

function renderQuestion(){
  state.answered = false;
  const total = state.deck.length;
  const q = state.deck[state.idx];
  app.innerHTML = "";
  app.appendChild(el(`
    <div>
      <div class="quiz-head">
        <span class="count">第 ${state.idx+1} / ${total} 题</span>
        <div class="progress" role="progressbar" aria-valuenow="${state.idx+1}" aria-valuemin="1" aria-valuemax="${total}"><i style="width:${(state.idx)/total*100}%"></i></div>
      </div>
      <span class="q-section">${SECTIONS[q.s]}</span>
      <p class="q-stem serif">${q.q}</p>
      <div class="opts" role="group" aria-label="选项">
        ${q.opts.map((t,i) => `
          <button class="opt" data-i="${i}">
            <span class="letter">${LETTERS[i]}</span>
            <span class="txt">${t}</span>
          </button>`).join("")}
      </div>
      <div class="feedback" id="fb" hidden></div>
      <div class="quiz-foot">
        <button class="btn btn-primary" id="next" hidden>${state.idx+1 === total ? "查看成绩" : "下一题"}</button>
      </div>
    </div>`));
  requestAnimationFrame(() => {
    const bar = app.querySelector(".progress>i");
    if(bar) bar.style.width = `${(state.idx)/total*100}%`;
  });
  app.querySelectorAll(".opt").forEach(b => b.addEventListener("click", () => pick(Number(b.dataset.i))));
  app.querySelector("#next").addEventListener("click", next);
  window.scrollTo({top:0, behavior:"smooth"});
}

function pick(i){
  if(state.answered) return;
  state.answered = true;
  const q = state.deck[state.idx];
  const ok = i === q.ans;
  if(ok) state.score++; else state.wrong.push(q);

  app.querySelectorAll(".opt").forEach((b,bi) => {
    b.disabled = true;
    if(bi === q.ans) b.classList.add("correct");
    else if(bi === i) b.classList.add("wrong");
  });

  const fb = app.querySelector("#fb");
  fb.hidden = false;
  fb.className = `feedback show ${ok ? "ok" : "no"}`;
  fb.innerHTML = `
    <div class="verdict">${ok ? ICON_OK + "回答正确" : ICON_NO + `回答错误，正确答案是 ${LETTERS[q.ans]}`}</div>
    <div class="exp">${q.e}</div>`;

  const bar = app.querySelector(".progress>i");
  if(bar) bar.style.width = `${(state.idx+1)/state.deck.length*100}%`;

  app.querySelector("#next").hidden = false;
  fb.scrollIntoView({block:"nearest", behavior:"smooth"});
}

function next(){
  if(state.idx + 1 < state.deck.length){
    state.idx++;
    renderQuestion();
  }else{
    renderResult();
  }
}

function renderResult(){
  const total = state.deck.length;
  const pct = Math.round(state.score/total*100);
  saveRecord({
    t: Date.now(),
    mode: state.modeName,
    total,
    score: state.score,
    dur: Math.round((Date.now() - state.startTime) / 1000),
  });
  app.innerHTML = "";
  app.appendChild(el(`
    <div class="card">
      <span class="q-section">本轮成绩</span>
      <div class="score-ring"><span class="big">${state.score}</span><span class="den">/ ${total} 题</span></div>
      <div class="stat-row">
        <span>正确率 <b>${pct}%</b></span>
        <span>答对 <b>${state.score}</b></span>
        <span>答错 <b>${total-state.score}</b></span>
      </div>
      ${state.wrong.length ? `
        <p style="font-weight:600;margin-bottom:4px">错题回顾（点任意一道可单独重练）：</p>
        <div class="wrong-list">
          ${state.wrong.map((q,i) => `
            <button class="wrong-item" data-i="${i}"><span class="n">${i+1}.</span>${q.q}</button>`).join("")}
        </div>` : `<p style="margin:12px 0 20px">全部答对，太稳了！</p>`}
      <div class="result-actions">
        ${state.wrong.length ? `<button class="btn btn-primary" id="retry">重练 ${state.wrong.length} 道错题</button>` : ""}
        <button class="btn btn-ghost" id="home">返回首页</button>
      </div>
    </div>`));
  const retry = app.querySelector("#retry");
  if(retry) retry.addEventListener("click", () => startQuiz(state.wrong));
  app.querySelectorAll(".wrong-item").forEach(b => b.addEventListener("click", () => {
    startQuiz([state.wrong[Number(b.dataset.i)]]);
  }));
  app.querySelector("#home").addEventListener("click", renderStart);
  window.scrollTo({top:0, behavior:"smooth"});
}

renderStart();
